#!/usr/bin/env node
import { execFileSync } from 'node:child_process';

export const MARKER_START = '<!-- missing-examples:start -->';
export const MARKER_END = '<!-- missing-examples:end -->';

const PREAMBLE = [
    'These akira-io/ui exports are referenced in no file under src/demos, so no example on the site shows them.',
    '',
    'Modules listed in tests/uncovered-entries.json, and symbols listed under its "symbols" key, are deliberately without an example and never show up here.',
];

const FOOTER =
    'Generated by flag-missing-examples.yml in akira-io/ui. Anything written outside the block above survives an update.';

export function parseEntries(text) {
    const entries = JSON.parse(text);

    if (!Array.isArray(entries)) {
        throw new Error(`the detector produced no JSON array: ${text}`);
    }

    return entries;
}

function sortKey({ group, slug, symbol }) {
    return `${group}/${slug}:${symbol ?? ''}`;
}

export function normalize(entries) {
    return [...entries].sort((left, right) =>
        sortKey(left).localeCompare(sortKey(right)),
    );
}

export function groupByModule(entries) {
    const modules = new Map();

    for (const { group, slug, symbol, specifier } of normalize(entries)) {
        const key = `${group}/${slug}`;
        const module = modules.get(key) ?? {
            module: key,
            specifiers: [],
            symbols: [],
        };

        if (!module.specifiers.includes(specifier)) {
            module.specifiers.push(specifier);
        }

        module.symbols.push(symbol);
        modules.set(key, module);
    }

    return [...modules.values()];
}

export function renderList(entries) {
    return groupByModule(entries)
        .flatMap(({ module, specifiers, symbols }) => [
            `- \`${module}\` from ${specifiers.map((specifier) => `\`${specifier}\``).join(', ')}`,
            ...symbols.map((symbol) => `  - \`${symbol}\``),
        ])
        .join('\n');
}

export function renderBlock(entries, runUrl) {
    return [
        MARKER_START,
        renderList(entries),
        '',
        '```json',
        JSON.stringify(normalize(entries)),
        '```',
        `Run: ${runUrl}`,
        MARKER_END,
    ].join('\n');
}

export function renderBody(entries, runUrl) {
    return [...PREAMBLE, '', renderBlock(entries, runUrl), '', FOOTER].join(
        '\n',
    );
}

function blockRanges(lines) {
    const ranges = [];

    for (let index = 0; index < lines.length; index += 1) {
        if (lines[index] !== MARKER_START) continue;

        let cursor = index + 1;

        while (
            cursor < lines.length &&
            lines[cursor] !== MARKER_START &&
            lines[cursor] !== MARKER_END
        ) {
            cursor += 1;
        }

        if (lines[cursor] !== MARKER_END) continue;

        ranges.push([index, cursor]);
        index = cursor;
    }

    return ranges;
}

function bodyLines(body) {
    return body.replace(/\r\n?/g, '\n').split('\n');
}

export function readRecordedEntries(body) {
    const lines = bodyLines(body);
    const [range] = blockRanges(lines);

    if (!range) return null;

    const recorded = lines
        .slice(range[0] + 1, range[1])
        .find((line) => line.startsWith('['));

    if (recorded === undefined) return null;

    try {
        const entries = JSON.parse(recorded);

        return Array.isArray(entries) ? entries : null;
    } catch {
        return null;
    }
}

export function replaceBlock(body, block) {
    const lines = bodyLines(body);
    const ranges = blockRanges(lines);

    if (ranges.length === 0) return null;

    const dropped = new Set();

    for (const [start, end] of ranges) {
        for (let index = start; index <= end; index += 1) dropped.add(index);
    }

    const [first] = ranges;

    return lines
        .flatMap((line, index) => {
            if (index === first[0]) return [block];
            if (dropped.has(index)) return [];

            return [line];
        })
        .join('\n');
}

export function sameEntries(left, right) {
    return (
        JSON.stringify(normalize(left)) === JSON.stringify(normalize(right))
    );
}

export function reportMissingExamples({ entries, repo, title, runUrl, gh }) {
    const open = JSON.parse(
        gh(['issue', 'list', '--repo', repo, '--state', 'open', '--limit', '100', '--json', 'number,title']) ||
            '[]',
    );
    const issue = open.find((candidate) => candidate.title === title);

    if (entries.length === 0) {
        if (!issue) return 'nothing is missing and no issue is open';

        gh([
            'issue',
            'comment',
            String(issue.number),
            '--repo',
            repo,
            '--body',
            `Every export now appears in a demo or sits in tests/uncovered-entries.json. Run: ${runUrl}`,
        ]);
        gh(['issue', 'close', String(issue.number), '--repo', repo]);

        return 'closed the issue';
    }

    if (!issue) {
        gh([
            'issue',
            'create',
            '--repo',
            repo,
            '--title',
            title,
            '--label',
            'documentation',
            '--assignee',
            'kidiatoliny',
            '--body',
            renderBody(entries, runUrl),
        ]);

        return 'opened the issue';
    }

    const number = String(issue.number);
    const body = JSON.parse(
        gh(['issue', 'view', number, '--repo', repo, '--json', 'body']),
    ).body;
    const recorded = readRecordedEntries(body);

    if (recorded && sameEntries(recorded, entries)) {
        return 'the list has not changed since the issue was last updated';
    }

    const updated =
        replaceBlock(body, renderBlock(entries, runUrl)) ??
        renderBody(entries, runUrl);

    gh(['issue', 'edit', number, '--repo', repo, '--body', updated]);
    gh([
        'issue',
        'comment',
        number,
        '--repo',
        repo,
        '--body',
        ['The list changed:', '', renderList(entries), '', `Run: ${runUrl}`].join('\n'),
    ]);

    return 'updated the issue';
}

function required(name) {
    const value = process.env[name];

    if (value === undefined) throw new Error(`${name} is required`);

    return value;
}

if (import.meta.url === `file://${process.argv[1]}`) {
    console.log(
        reportMissingExamples({
            entries: parseEntries(required('MISSING')),
            repo: required('SITE_REPO'),
            title: required('ISSUE_TITLE'),
            runUrl: process.env.RUN_URL ?? '',
            gh: (args) => execFileSync('gh', args, { encoding: 'utf8' }),
        }),
    );
}
